import{_ as t,o,c as a,a2 as i}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"archied  --  design notes","description":"","frontmatter":{},"headers":[],"relativePath":"archive/DESIGN.md","filePath":"archive/DESIGN.md","lastUpdated":1785228410000}'),n={name:"archive/DESIGN.md"};function r(s,e,l,d,c,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="archied-design-notes" tabindex="-1">archied -- design notes <a class="header-anchor" href="#archied-design-notes" aria-label="Permalink to &quot;archied  --  design notes&quot;">​</a></h1><p>Archie is a resident daemon that keeps personal projects moving: it polls GitHub for issues labelled <code>archie</code>, works each one in an isolated fresh-clone worktree through a routed <strong>workflow</strong>, and opens a pull request for human review. Sam reviews and merges; the machine grinds in between.</p><p>Guiding principle: <strong>environmental constraints over prompt instructions.</strong> Agents don&#39;t get asked nicely to write good code -- the quality gate (vet/build/test/lint, configurable per repo and per workflow stage) refuses to let a run succeed until it passes. The gate mechanics live in <code>ai-sdk/agentloop</code>; this repo owns orchestration only.</p><h2 id="workflows-not-a-pipeline" tabindex="-1">Workflows, not a pipeline <a class="header-anchor" href="#workflows-not-a-pipeline" aria-label="Permalink to &quot;Workflows, not a pipeline&quot;">​</a></h2><p><code>internal/workflow</code> is the engine: a Workflow is an ordered list of stages over a shared TaskContext; stages are deterministic steps (worktree, gate, diff cap, PR, comments -- the shared step library in <code>steps.go</code>) or agent stages (<code>agentloop.Run</code> with a stage-specific mission/toolset/gate). Routing is label-driven (<code>bug</code> → tdd, <code>feature</code> → feasibility, default → implement), refinable by an LLM triage stage. Adding a workflow must never require touching the engine or reimplementing steps.</p><p>Planned workflows:</p><ul><li><strong>bootstrap</strong> (registered): deterministic marker-file PR proving invites/clone/push/PR plumbing.</li><li><strong>implement</strong>: planner (read-only agentloop, plan posted to the issue) → builder (full toolset, repo gate) → diff cap → PR.</li><li><strong>tdd</strong> (bugfixes): analyse → problem surface → write failing repro tests (gate stage with <code>ExpectFailure</code>) → fix (gate: suite passes) → PR.</li><li><strong>feasibility</strong> (features): read-only analysis → roadmap fit → won&#39;t-do close with reasons, or plan + PRD → email Sam → <code>waiting_human</code> → LLM-judged reply → hand off to implement.</li></ul><h2 id="task-lifecycle" tabindex="-1">Task lifecycle <a class="header-anchor" href="#task-lifecycle" aria-label="Permalink to &quot;Task lifecycle&quot;">​</a></h2><p><code>queued → running(workflow:stage) → waiting_human | pr_open → merged | parked | rejected | closed_wont_do</code></p><p>SQLite (<code>internal/store</code>), WAL, one row per issue with a transitions audit table. Crash recovery: <code>running</code> tasks re-queue on startup with attempt++. Parks are never silent -- every park comments on the issue with the reason and gate output.</p><h2 id="security-posture" tabindex="-1">Security posture <a class="header-anchor" href="#security-posture" aria-label="Permalink to &quot;Security posture&quot;">​</a></h2><ul><li>Fine-grained PAT on the bot account only (Contents RW, PRs RW, Issues RW, Metadata R), via <code>ARCHIE_GITHUB_TOKEN</code>; git auth through an askpass helper so the token stays out of argv and <code>.git/config</code>.</li><li>The model never runs git: <code>internal/worktree</code> owns all repo operations deterministically.</li><li>Agent tools are jailed to the task worktree (toolkit path jail); intended deployment is a dedicated Incus container so the blast radius is environmental, not prompt-negotiated.</li></ul>',12)])])}const h=t(n,[["render",r]]);export{g as __pageData,h as default};
